insert into public.translations (locale, key, value) values
  ('pt-BR', 'claude.permission.default.hint', $json$"O Claude Code no modo padrão: ações sensíveis pedem aprovação. No modo Desenvolvimento o JayV ainda o deixa editar os arquivos do projeto, porque ninguém consegue aprovar pelo chat."$json$::jsonb),
  ('pt-BR', 'codex.sandbox.read-only.hint', $json$"Lê o projeto e responde sem mudar nada. No modo Desenvolvimento o JayV ainda o deixa escrever no projeto."$json$::jsonb),
  ('pt-BR', 'copilot.access.read.hint', $json$"Responde sem editar arquivos nem rodar comandos. No modo Desenvolvimento o JayV ainda o deixa editar arquivos."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.buildWrites.title', $json$"O modo Desenvolvimento volta a editar arquivos"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.buildWrites.detail', $json$"No modo Desenvolvimento o agente rodava com toda escrita negada, porque esperava uma aprovação que ninguém conseguia dar pelo chat. Agora o Claude Code edita os arquivos do projeto sem perguntar, o Codex escreve dentro do projeto e o Copilot pode editar arquivos; os comandos seguem as suas configurações. Se a regra de escrita do Jev ou a da sua organização for Negar, o agente continua só lendo. O agente também parou de oferecer opções que o app não tem, como aprovar um pedido de permissão."$json$::jsonb),
  ('en', 'claude.permission.default.hint', $json$"Claude Code's default mode: sensitive actions ask for approval. In Development mode JayV still lets it edit project files, since nobody can approve from the chat."$json$::jsonb),
  ('en', 'codex.sandbox.read-only.hint', $json$"Reads the project and answers without changing anything. In Development mode JayV still lets it write to the project."$json$::jsonb),
  ('en', 'copilot.access.read.hint', $json$"Answers without editing files or running commands. In Development mode JayV still lets it edit files."$json$::jsonb),
  ('en', 'whatsNew.item.buildWrites.title', $json$"Development mode edits files again"$json$::jsonb),
  ('en', 'whatsNew.item.buildWrites.detail', $json$"In Development mode the agent ran with every write denied, because it waited for an approval nobody could give from the chat. Claude Code now edits project files without asking, Codex writes inside the project and Copilot may edit files; commands still follow your settings. If Jev's write rule or your organization's is Deny, the agent stays read-only. The agent also stopped offering options the app does not have, such as approving a permission prompt."$json$::jsonb),
  ('es', 'claude.permission.default.hint', $json$"Modo predeterminado de Claude Code: las acciones sensibles piden aprobación. En el modo Desarrollo, JayV igual le deja editar los archivos del proyecto, porque nadie puede aprobar desde el chat."$json$::jsonb),
  ('es', 'codex.sandbox.read-only.hint', $json$"Lee el proyecto y responde sin cambiar nada. En el modo Desarrollo, JayV igual le deja escribir en el proyecto."$json$::jsonb),
  ('es', 'copilot.access.read.hint', $json$"Responde sin editar archivos ni ejecutar comandos. En el modo Desarrollo, JayV igual le deja editar archivos."$json$::jsonb),
  ('es', 'whatsNew.item.buildWrites.title', $json$"El modo Desarrollo vuelve a editar archivos"$json$::jsonb),
  ('es', 'whatsNew.item.buildWrites.detail', $json$"En el modo Desarrollo el agente funcionaba con toda escritura denegada, porque esperaba una aprobación que nadie podía dar desde el chat. Ahora Claude Code edita los archivos del proyecto sin preguntar, Codex escribe dentro del proyecto y Copilot puede editar archivos; los comandos siguen tu configuración. Si la regla de escritura de Jev o la de tu organización es Denegar, el agente sigue solo leyendo. El agente también dejó de ofrecer opciones que la app no tiene, como aprobar una solicitud de permiso."$json$::jsonb),
  ('zh-CN', 'claude.permission.default.hint', $json$"Claude Code 的默认模式：敏感操作需要批准。在开发模式下，JayV 仍允许它编辑项目文件，因为无法在聊天中批准。"$json$::jsonb),
  ('zh-CN', 'codex.sandbox.read-only.hint', $json$"读取项目并回答，不做任何更改。在开发模式下，JayV 仍允许它写入项目。"$json$::jsonb),
  ('zh-CN', 'copilot.access.read.hint', $json$"回答时不编辑文件也不运行命令。在开发模式下，JayV 仍允许它编辑文件。"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.buildWrites.title', $json$"开发模式恢复编辑文件"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.buildWrites.detail', $json$"在开发模式下，代理运行时所有写入都被拒绝，因为它在等待一个无法在聊天中给出的批准。现在 Claude Code 无需询问即可编辑项目文件，Codex 可在项目内写入，Copilot 可以编辑文件；命令仍遵循你的设置。如果 Jev 或你所在组织的写入规则为拒绝，代理仍只读。代理也不再提供应用中不存在的选项，例如批准权限请求。"$json$::jsonb),
  ('hi', 'claude.permission.default.hint', $json$"Claude Code का डिफ़ॉल्ट मोड: संवेदनशील कार्य अनुमति माँगते हैं। डेवलपमेंट मोड में JayV फिर भी उसे प्रोजेक्ट की फ़ाइलें बदलने देता है, क्योंकि चैट से कोई अनुमति नहीं दे सकता।"$json$::jsonb),
  ('hi', 'codex.sandbox.read-only.hint', $json$"प्रोजेक्ट पढ़ता है और कुछ बदले बिना जवाब देता है। डेवलपमेंट मोड में JayV फिर भी उसे प्रोजेक्ट में लिखने देता है।"$json$::jsonb),
  ('hi', 'copilot.access.read.hint', $json$"फ़ाइलें बदले या कमांड चलाए बिना जवाब देता है। डेवलपमेंट मोड में JayV फिर भी उसे फ़ाइलें बदलने देता है।"$json$::jsonb),
  ('hi', 'whatsNew.item.buildWrites.title', $json$"डेवलपमेंट मोड फिर से फ़ाइलें बदलता है"$json$::jsonb),
  ('hi', 'whatsNew.item.buildWrites.detail', $json$"डेवलपमेंट मोड में एजेंट हर लेखन अस्वीकृत होने के साथ चलता था, क्योंकि वह ऐसी अनुमति का इंतज़ार करता था जो चैट से कोई नहीं दे सकता था। अब Claude Code बिना पूछे प्रोजेक्ट की फ़ाइलें बदलता है, Codex प्रोजेक्ट के अंदर लिखता है और Copilot फ़ाइलें बदल सकता है; कमांड आपकी सेटिंग्स के अनुसार ही चलते हैं। अगर Jev का या आपके संगठन का लेखन नियम अस्वीकार है, तो एजेंट सिर्फ़ पढ़ता रहता है। एजेंट अब ऐसे विकल्प भी नहीं देता जो ऐप में नहीं हैं, जैसे अनुमति अनुरोध स्वीकार करना।"$json$::jsonb),
  ('ar', 'claude.permission.default.hint', $json$"الوضع الافتراضي لـ Claude Code: الإجراءات الحساسة تطلب الموافقة. في وضع التطوير يسمح له JayV مع ذلك بتعديل ملفات المشروع، لأن لا أحد يستطيع الموافقة من الدردشة."$json$::jsonb),
  ('ar', 'codex.sandbox.read-only.hint', $json$"يقرأ المشروع ويجيب دون تغيير أي شيء. في وضع التطوير يسمح له JayV مع ذلك بالكتابة في المشروع."$json$::jsonb),
  ('ar', 'copilot.access.read.hint', $json$"يجيب دون تعديل الملفات أو تشغيل الأوامر. في وضع التطوير يسمح له JayV مع ذلك بتعديل الملفات."$json$::jsonb),
  ('ar', 'whatsNew.item.buildWrites.title', $json$"وضع التطوير يعدّل الملفات من جديد"$json$::jsonb),
  ('ar', 'whatsNew.item.buildWrites.detail', $json$"في وضع التطوير كان الوكيل يعمل مع رفض كل كتابة، لأنه كان ينتظر موافقة لا يستطيع أحد منحها من الدردشة. الآن يعدّل Claude Code ملفات المشروع دون أن يسأل، ويكتب Codex داخل المشروع، ويمكن لـ Copilot تعديل الملفات؛ وتظل الأوامر تتبع إعداداتك. إذا كانت قاعدة الكتابة في Jev أو في مؤسستك هي الرفض، يبقى الوكيل للقراءة فقط. كما توقف الوكيل عن عرض خيارات لا يوفرها التطبيق، مثل الموافقة على طلب إذن."$json$::jsonb),
  ('fr', 'claude.permission.default.hint', $json$"Mode par défaut de Claude Code : les actions sensibles demandent une approbation. En mode Développement, JayV le laisse tout de même modifier les fichiers du projet, car personne ne peut approuver depuis le chat."$json$::jsonb),
  ('fr', 'codex.sandbox.read-only.hint', $json$"Lit le projet et répond sans rien modifier. En mode Développement, JayV le laisse tout de même écrire dans le projet."$json$::jsonb),
  ('fr', 'copilot.access.read.hint', $json$"Répond sans modifier de fichiers ni lancer de commandes. En mode Développement, JayV le laisse tout de même modifier des fichiers."$json$::jsonb),
  ('fr', 'whatsNew.item.buildWrites.title', $json$"Le mode Développement modifie à nouveau les fichiers"$json$::jsonb),
  ('fr', 'whatsNew.item.buildWrites.detail', $json$"En mode Développement, l'agent tournait avec toute écriture refusée, car il attendait une approbation que personne ne pouvait donner depuis le chat. Claude Code modifie désormais les fichiers du projet sans demander, Codex écrit dans le projet et Copilot peut modifier des fichiers ; les commandes suivent toujours vos réglages. Si la règle d'écriture de Jev ou celle de votre organisation est Refuser, l'agent reste en lecture seule. L'agent ne propose plus non plus d'options que l'app n'a pas, comme approuver une demande d'autorisation."$json$::jsonb),
  ('ru', 'claude.permission.default.hint', $json$"Режим Claude Code по умолчанию: чувствительные действия требуют одобрения. В режиме разработки JayV всё равно разрешает ему менять файлы проекта, потому что одобрить из чата никто не может."$json$::jsonb),
  ('ru', 'codex.sandbox.read-only.hint', $json$"Читает проект и отвечает, ничего не меняя. В режиме разработки JayV всё равно разрешает ему писать в проект."$json$::jsonb),
  ('ru', 'copilot.access.read.hint', $json$"Отвечает, не редактируя файлы и не запуская команды. В режиме разработки JayV всё равно разрешает ему редактировать файлы."$json$::jsonb),
  ('ru', 'whatsNew.item.buildWrites.title', $json$"Режим разработки снова редактирует файлы"$json$::jsonb),
  ('ru', 'whatsNew.item.buildWrites.detail', $json$"В режиме разработки агент работал с запретом на любую запись, потому что ждал одобрения, которое никто не мог дать из чата. Теперь Claude Code меняет файлы проекта без вопросов, Codex пишет внутри проекта, а Copilot может редактировать файлы; команды по-прежнему подчиняются вашим настройкам. Если правило записи Jev или вашей организации — «Запретить», агент остаётся только для чтения. Агент также перестал предлагать то, чего в приложении нет, например одобрить запрос разрешения."$json$::jsonb),
  ('ja', 'claude.permission.default.hint', $json$"Claude Code の既定モード：重要な操作は承認を求めます。開発モードでは、チャットから承認できないため、JayV はプロジェクトのファイル編集を許可します。"$json$::jsonb),
  ('ja', 'codex.sandbox.read-only.hint', $json$"プロジェクトを読み、何も変更せずに回答します。開発モードでは、JayV はプロジェクトへの書き込みを許可します。"$json$::jsonb),
  ('ja', 'copilot.access.read.hint', $json$"ファイルの編集もコマンドの実行もせずに回答します。開発モードでは、JayV はファイルの編集を許可します。"$json$::jsonb),
  ('ja', 'whatsNew.item.buildWrites.title', $json$"開発モードで再びファイルを編集できるように"$json$::jsonb),
  ('ja', 'whatsNew.item.buildWrites.detail', $json$"開発モードでは、チャットから誰も出せない承認を待っていたため、エージェントの書き込みがすべて拒否されていました。現在は Claude Code が確認なしでプロジェクトのファイルを編集し、Codex はプロジェクト内に書き込み、Copilot はファイルを編集できます。コマンドは引き続き設定に従います。Jev または組織の書き込みルールが「拒否」の場合、エージェントは読み取り専用のままです。また、権限リクエストの承認など、アプリにない選択肢を提示しなくなりました。"$json$::jsonb),
  ('de', 'claude.permission.default.hint', $json$"Standardmodus von Claude Code: Heikle Aktionen fragen nach Freigabe. Im Entwicklungsmodus lässt JayV es trotzdem Projektdateien bearbeiten, weil im Chat niemand freigeben kann."$json$::jsonb),
  ('de', 'codex.sandbox.read-only.hint', $json$"Liest das Projekt und antwortet, ohne etwas zu ändern. Im Entwicklungsmodus lässt JayV es trotzdem ins Projekt schreiben."$json$::jsonb),
  ('de', 'copilot.access.read.hint', $json$"Antwortet, ohne Dateien zu bearbeiten oder Befehle auszuführen. Im Entwicklungsmodus lässt JayV es trotzdem Dateien bearbeiten."$json$::jsonb),
  ('de', 'whatsNew.item.buildWrites.title', $json$"Der Entwicklungsmodus bearbeitet wieder Dateien"$json$::jsonb),
  ('de', 'whatsNew.item.buildWrites.detail', $json$"Im Entwicklungsmodus lief der Agent mit jedem Schreibzugriff verweigert, weil er auf eine Freigabe wartete, die im Chat niemand geben konnte. Jetzt bearbeitet Claude Code Projektdateien ohne Nachfrage, Codex schreibt innerhalb des Projekts und Copilot darf Dateien bearbeiten; Befehle folgen weiter deinen Einstellungen. Ist die Schreibregel von Jev oder deiner Organisation Verweigern, bleibt der Agent nur lesend. Außerdem bietet der Agent keine Optionen mehr an, die die App nicht hat, etwa eine Berechtigungsanfrage freizugeben."$json$::jsonb)
